/// @namespace Compliance
model shopping_mall_ai_audit_logs {
  /// Primary Key.
  id String @id @db.Uuid

  /// Type of entity or business object affected (e.g., 'order', 'product', 'user').
  entity_type String
  /// ID of the affected object; references may map to multiple domains.
  entity_id String
  /// Actor who took the action (user/admin/seller/system); nullable for system events.
  actor_id String?
  /// Role of the actor (e.g., customer, seller, admin, system).
  actor_role String
  /// Description of the operation performed (e.g., 'update', 'delete', 'permission_change').
  operation String
  /// Detailed info about the change (diff, before/after, JSON, etc.).
  detail String
  /// Timestamp when action occurred.
  occurred_at DateTime
  /// IP address or session.
  context String?
  /// Soft delete marker for retention policies.
  deleted_at DateTime?
  @@index([entity_type, entity_id])
  @@index([actor_id, occurred_at])
}

model shopping_mall_ai_policy_changes {
  /// Primary Key.
  id String @id @db.Uuid

  /// Policy/document identifier (e.g., 'privacy_policy', 'terms_of_service').
  policy_code String
  /// Version string for changed policy.
  policy_version String
  /// Description of policy change.
  change_summary String
  /// Approver/admin ID.
  approved_by String
  /// Timestamp when change was approved/published.
  approved_at DateTime
  /// Previous policy version (nullable for initial release).
  previous_version String?
  /// Soft delete marker for retention.
  deleted_at DateTime?
  @@unique([policy_code, policy_version])
  @@index([approved_by, approved_at])
}

model shopping_mall_ai_legal_consents {
  /// Primary Key.
  id String @id @db.Uuid

  /// ID of consenting user (customer/seller/admin fk reference as string).
  user_id String
  /// Policy/document code referenced.
  policy_code String
  /// Version accepted.
  policy_version String
  /// Timestamp of consent.
  consented_at DateTime
  /// Consent method (e.g., user, admin, system-migrated).
  consent_method String
  /// Withdrawn marker: time at which consent was withdrawn.
  withdrawn_at DateTime?
  /// IP at the time of consent.
  consent_ip String?
  /// Soft delete marker for retention policies.
  deleted_at DateTime?
  @@unique([user_id, policy_code, policy_version])
  @@index([policy_code, policy_version])
}

model shopping_mall_ai_analytics_exports {
  /// Primary Key.
  id String @id @db.Uuid

  /// Type of export (e.g., 'order', 'user_activity', 'sales').
  export_type String
  /// Description/context for export reason.
  export_reason String
  /// Filename or URI where export is stored.
  export_uri String
  /// Who/what requested export; admin/user ID or system process.
  requested_by String
  /// Timestamp when export was generated.
  exported_at DateTime
  /// Data retention (delete after this timestamp); nullable means permanent.
  delete_after DateTime?
  /// Export status (pending, completed, failed, archived).
  status String
  /// Soft delete marker for audit retention.
  deleted_at DateTime?
  @@index([export_type, export_reason])
  @@index([requested_by, exported_at])
}

