model shopping_mall_ai_shipments {
  /// Primary Key.
  id String @id @db.Uuid

  /// Order this shipment is for (FK to shopping_mall_ai_orders).
  shopping_mall_ai_order_id String @db.Uuid
  order shopping_mall_ai_orders @relation(fields: [shopping_mall_ai_order_id], references: [id])

  /// Shipment status (e.g. pending, shipped, in_transit, delivered, returned).
  status String

  /// Tracking number for this shipment.
