/// @namespace Orders
model shopping_mall_ai_orders {
  /// Primary Key - Implements the need for unique identification of each order event. Used for strict auditability and 3NF compliance. E.g., used during order placement and post-payment analytics.
  id String @id @db.Uuid

  /// Customer placing the order; references external identity for audit, reporting, and customer support. Maintains 3NF as customer data is separate. E.g., used for purchase history display.
  shopping_mall_ai_customer_id String @db.Uuid
  customer shopping_mall_ai_customers @relation(fields: [shopping_mall_ai_customer_id], references: [id])

  /// Channel context (e.g., web, mobile, marketplace) for order origination. Ensures auditability and allows segmented performance reporting. 3NF; channel lookup remains normalized.
  shopping_mall_ai_channel_id String @db.Uuid
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id])

  /// Order status; codes defined in the business process, values are flexible. E.g., pending, paid, shipped, completed. Ensures current order state can be tracked accurately for workflow control. 
  status String

  /// Timestamp: order creation. For audit trail and analytics.
  created_at DateTime

  /// Timestamp: last update (e.g., status change).
  updated_at DateTime

  /// Order item breakdown for this order (1:N).
  order_items shopping_mall_ai_order_items[]

  /// Payment detail breakdown for this order (1:N).
  payments shopping_mall_ai_payments[]

  /// Fulfillment/shipment details (0:N).
  shipments shopping_mall_ai_shipments[]

  @@index([shopping_mall_ai_customer_id, created_at])
  @@index([shopping_mall_ai_channel_id, created_at])
}

model shopping_mall_ai_order_items {
  /// Primary Key for each product/option included in an order. Ensures unique, atomic traceability for reporting and returns. 3NF compliance; no product/item redundancy.
  id String @id @db.Uuid

  /// Parent order (FK). Each item references a singular order for full transactional normalization.
  shopping_mall_ai_order_id String @db.Uuid
  order shopping_mall_ai_orders @relation(fields: [shopping_mall_ai_order_id], references: [id])

  /// Product reference; external, 3NF normalized. Core for inventory sync and SKU-level reporting.
  shopping_mall_ai_product_id String @db.Uuid
  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id])

  /// Option/variant reference (nullable). Allows distinct pricing/options without denormalization. Maintains normalization; supports variant analytics. E.g., color/size.
  shopping_mall_ai_product_option_id String? @db.Uuid
  product_option shopping_mall_ai_product_options? @relation(fields: [shopping_mall_ai_product_option_id], references: [id])

  /// Price at order time, not recalculated. Ensures historical audit compliance.
  price Double

  /// Quantity ordered (always atomic, always positive). Maintains normalization.
  quantity Int

  /// Line status code for returns/cancellations tracking (values reflect business process state machine).
  status String

  /// Timestamp: created.
  created_at DateTime

  /// Timestamp: last updated.
  updated_at DateTime

  @@index([shopping_mall_ai_order_id, created_at])
  @@index([shopping_mall_ai_product_id])
}

model shopping_mall_ai_payments {
  /// Unique transaction ID for payment events. Ensures audit compliance, supports multiple methods per order. 3NF, one record per attempt.
  id String @id @db.Uuid

  /// Related order for payment reconciliation. 1:N, not denormalized.
  shopping_mall_ai_order_id String @db.Uuid
  order shopping_mall_ai_orders @relation(fields: [shopping_mall_ai_order_id], references: [id])

  /// Payment method code (e.g., card, deposit, coupon). Flexible for business expansion, supports analytics.
  method String

  /// Payment status (e.g., pending, success, failed, refunded). Business codeset for workflow. No aggregates stored.
  status String

  /// Amount tendered (stored at event time for historical accuracy).
  amount Double

  /// Timestamp: initiated. For full auditability.
  initiated_at DateTime

  /// Timestamp: completion/failure. Nullable until resolved.
  resolved_at DateTime?

  /// FK: Payment channel, 3NF compliance for cross-channel reporting.
  shopping_mall_ai_channel_id String @db.Uuid
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id])

  @@index([shopping_mall_ai_order_id, initiated_at])
  @@index([shopping_mall_ai_channel_id])
}

model shopping_mall_ai_shipments {
  /// Atomic shipment/fulfillment record, supports 1:N per order for partial shipments. 3NF, no denormalization.
  id String @id @db.Uuid

  /// Parent order (FK). Allows order-level shipment splits.
  shopping_mall_ai_order_id String @db.Uuid
  order shopping_mall_ai_orders @relation(fields: [shopping_mall_ai_order_id], references: [id])

  /// Shipment current status (business codes).
  status String

  /// Tracking code (nullable for non-tracked or pickup orders).
  tracking_number String?

  /// Fulfillment provider name (nullable, free text/lookup).
  provider String?

  /// Timestamp: created.
  created_at DateTime

  /// Timestamp: last event/change/delivery.
  updated_at DateTime

  @@index([shopping_mall_ai_order_id, created_at])
}

