/// @namespace Carts
model shopping_mall_ai_carts {
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer who owns the cart (nullable for guest carts). Implements requirement for tracking member and guest carts. Maintains normalization by using customer_id FK rather than duplicating data. For example, a member cart is linked with a customer, a guest cart leaves this null.
  shopping_mall_ai_customer_id String? @db.Uuid
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id])

  /// Seller (only present if the cart is tied to a specific seller's catalog, e.g. for split-cart multi-seller shopping). Business requirement: support multi-seller/multi-cart workflows. Maintains 3NF by isolating seller reference from core cart data. Usage example: each seller gets a separate cart instance at checkout for their items.
  shopping_mall_ai_seller_id String? @db.Uuid
  seller shopping_mall_ai_sellers? @relation(fields: [shopping_mall_ai_seller_id], references: [id])

  /// Channel from which the cart was created (e.g., web, app, partner integration). Maintains normalization and enables channel-specific analytics. For example, a cart started on the web has a channel_id for lookups and filtering.
  shopping_mall_ai_channel_id String @db.Uuid
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id])

  /// Section/category for context within the mall (analytics, campaign applicability).
  shopping_mall_ai_section_id String @db.Uuid
  section shopping_mall_ai_sections @relation(fields: [shopping_mall_ai_section_id], references: [id])

  /// Last update timestamp (used to expire abandoned carts).
  updated_at DateTime
  /// Creation timestamp for auditability and analytics.
  created_at DateTime

  /// List of items currently in the cart. Maintains normalization via linking table.
  cart_items shopping_mall_ai_cart_items[]

  /// Cart sessions tied (guest/member session management).
  cart_session shopping_mall_ai_cart_sessions[]

  @@index([shopping_mall_ai_customer_id, shopping_mall_ai_channel_id])
  @@index([updated_at])
}

model shopping_mall_ai_cart_items {
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent cart. Business mapping for associating items to carts. Enforces referential integrity.
  shopping_mall_ai_cart_id String @db.Uuid
  cart shopping_mall_ai_carts @relation(fields: [shopping_mall_ai_cart_id], references: [id])

  /// Product selected by the user.
  shopping_mall_ai_product_id String @db.Uuid
  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id])

  /// Product option (e.g., color/size variants; optional).
  shopping_mall_ai_product_option_id String? @db.Uuid
  product_option shopping_mall_ai_product_options? @relation(fields: [shopping_mall_ai_product_option_id], references: [id])

  /// Quantity the user intends to purchase. Atomic value to maintain 1NF.
  quantity Int
  /// Timestamp when item was added to the cart.
  added_at DateTime
  /// Last modification timestamp. Used for audit, conflict resolution, and analytics.
  updated_at DateTime

  @@index([shopping_mall_ai_cart_id, shopping_mall_ai_product_id])
}

model shopping_mall_ai_cart_sessions {
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked cart for this session.
  shopping_mall_ai_cart_id String @db.Uuid
  cart shopping_mall_ai_carts @relation(fields: [shopping_mall_ai_cart_id], references: [id])

  /// Session token — ties ephemeral session to a cart for guest workflows.
  session_token String
  /// Timestamp of session creation.
  created_at DateTime
  /// Timestamp of last cart access (for expiry and idle management).
  last_active_at DateTime

  @@unique([session_token])
  @@index([shopping_mall_ai_cart_id])
}

