  id String @id @db.Uuid

  /// Associated channel's primary key reference ({@link shopping_mall_ai_channels.id}). Maintains referential integrity for cross-section/channel hierarchy.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Section code for business logic and navigation mapping (e.g., 'home', 'products'). Implements atomicity and enables unique business lookup per channel. 3NF: no code redundancy within channel.
  code String

  /// Admin-facing section name for labeling and reporting. Separated from code for normalization/usability.
  name String

  /// Section enabled/disabled toggle for runtime configuration and navigation control. Enables UX flexibility without data deletion. 3NF: atomic, non-redundant.
  active Boolean

  /// Section-specific extensibility point for arbitrary configuration (JSON as string). Implements open-ended setup without denormalizing core entity.
  config String

  /// Creation timestamp for section, supporting audit trail of platform structure. Implements audit consistency across entities.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (for admin/ops audit and troubleshooting). 3NF compliance: strictly atomic fact.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
