  admin shopping_mall_ai_admins? @relation(fields: [shopping_mall_ai_admin_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_a_ae5f4826")

  @@index([shopping_mall_ai_seller_id], map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_s_73d5dca1")
  @@index([shopping_mall_ai_admin_id], map: "shopping_mall_ai_seller_onboardings_shopping_mall_ai_a_4139faf3")
